from .common import *


def candidate(root):
    c=constants(root/'scripts/lint_generated_index_sources.py')
    stages=[S('index_aliases',"SELECT __path,alias name,id FROM a WHERE kind='alias' AND name='Index' AND EXISTS(SELECT 1 FROM a p WHERE p.__path=a.__path AND p.id=a.parent AND p.kind='ImportFrom' AND p.module='l1000_schema.schema_def') AND alias!=''",('__path','name')),
      S('schema_aliases',"SELECT __path,CASE WHEN alias='' THEN 'schema_def' ELSE alias END name,id FROM a WHERE kind='alias' AND name='l1000_schema.schema_def' AND EXISTS(SELECT 1 FROM a p WHERE p.__path=a.__path AND p.id=a.parent AND p.kind='Import')",('__path','name')),
      S('index_calls',"SELECT n.* FROM calls n WHERE n.callee_kind='Name' AND (n.callee='Index' OR EXISTS(SELECT 1 FROM index_aliases s WHERE s.__path=n.__path AND s.name=n.callee AND s.id<n.id)) OR n.callee_kind='Attribute' AND n.callee='Index' AND n.receiver_kind='Name' AND (n.receiver_name='schema_def' OR EXISTS(SELECT 1 FROM schema_aliases s WHERE s.__path=n.__path AND s.name=n.receiver_name AND s.id<n.id))",('__path','id')),
      S('source_parameters',"SELECT p.*,v.annotation AS source_annotation FROM parameters p LEFT JOIN a v ON v.__path=p.__path AND v.parent=p.id AND v.field='annotation' WHERE p.name='source' AND p.field IN ('args','kwonlyargs')",('__path','fn')),
      S('kw_defaults',"SELECT d.*,(SELECT count(*) FROM a prior WHERE prior.__path=d.__path AND prior.parent=d.parent AND prior.field='kwonlyargs' AND prior.position<d.position) position_before FROM a d WHERE d.field='kw_defaults'",('__path','parent','position'))]
    rows=[row('missing_source',q('generated indexes must use _generated_index(..., source=IndexSource.*)'),'index_calls n LEFT JOIN functions f ON f.__path=n.__path AND f.id=n.fn',"coalesce(f.name,'')!='_generated_index'"),
      row('missing_source',q('_generated_index must forward source=source into Index(...)'),'index_calls n JOIN functions f ON f.__path=n.__path AND f.id=n.fn',"f.name='_generated_index' AND NOT EXISTS(SELECT 1 FROM a kw JOIN a v ON v.__path=kw.__path AND v.parent=kw.id AND v.field='value' WHERE kw.__path=n.__path AND kw.parent=n.id AND kw.field='keywords' AND kw.name='source' AND kw.position=(SELECT min(first.position) FROM a first WHERE first.__path=kw.__path AND first.parent=kw.parent AND first.field='keywords' AND first.name='source') AND v.kind='Name' AND v.name='source')"),
      row('missing_source',q('_generated_index must require a source: IndexSource parameter'),'functions n',"n.kind='FunctionDef' AND n.name='_generated_index' AND NOT EXISTS(SELECT 1 FROM source_parameters p WHERE p.__path=n.__path AND p.fn=n.id)"),
      row('missing_source',q('_generated_index source parameter must be annotated as IndexSource'),'functions n JOIN source_parameters p ON p.__path=n.__path AND p.fn=n.id',"n.kind='FunctionDef' AND n.name='_generated_index' AND coalesce(p.source_annotation,'')!='IndexSource'",order='n.id+0.001'),
      row('missing_source',q('_generated_index source must not default to MODEL_DECLARED'),'functions n JOIN parameters p ON p.__path=n.__path AND p.fn=n.id JOIN a arglist ON arglist.__path=p.__path AND arglist.id=p.parent JOIN a d ON d.__path=arglist.__path AND d.parent=arglist.id AND d.field=\'kw_defaults\' AND d.position=p.position',"n.kind='FunctionDef' AND n.name='_generated_index' AND p.field='kwonlyargs' AND p.name='source' AND (d.kind='Name' AND d.name='MODEL_DECLARED' OR d.kind='Attribute' AND d.name='MODEL_DECLARED' AND "+child('d','value',alias='value',condition="value.kind='Name' AND value.name='IndexSource'")+')',order='n.id+0.002')]
    return make_document('generated_index_sources',[triggered(make_clause('generated-index-source',stages,' UNION ALL '.join(rows)),['Index(','_generated_index','IndexSource'])],['impl/common/l7245_versioned_backends/generic_sparse.py'])
